-- 030: incidentes de seguridad.
-- 1) Datos abiertos del ECU 911 (Base de Emergencias, CC-BY) agregados por parroquia, mes y dia
--    de la semana. La base abierta no trae hora ni coordenadas; el detalle llega a parroquia.
-- 2) Reportes de los propios corredores (incidentes_usuario) con ubicacion GPS y hora del
--    dispositivo. El publico solo ve una version anonima (celda de ~110 m, hora truncada).
-- 3) nivel_seguridad_ruta(): nivel bajo / medio / alto por tramo y para la ruta completa.
-- Numero 030 para no chocar con las migraciones de la rama feat/rutas-loja-reportes.
-- Idempotente: se puede volver a ejecutar.

-- Parroquias (DPA INEC 2020, servidor idgn.ecuadorencifras.gob.ec, capa DPA_2020/INEC_PAR_A).
-- Poblacion: capa parroquias_pob del mismo servidor. Geometria simplificada (~30 m).
CREATE TABLE IF NOT EXISTS public.parroquias (
  cod_parroquia TEXT PRIMARY KEY CHECK (cod_parroquia ~ '^[0-9]{6}$'),
  nombre TEXT NOT NULL,
  canton TEXT NOT NULL,
  provincia TEXT NOT NULL,
  poblacion INTEGER,
  geom geometry(MultiPolygon, 4326) NOT NULL
);
CREATE INDEX IF NOT EXISTS parroquias_geom_idx ON public.parroquias USING gist (geom);
ALTER TABLE public.parroquias ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Parroquias: lectura publica" ON public.parroquias;
CREATE POLICY "Parroquias: lectura publica" ON public.parroquias FOR SELECT USING (true);
DROP POLICY IF EXISTS "Parroquias: gestion admin" ON public.parroquias;
CREATE POLICY "Parroquias: gestion admin" ON public.parroquias FOR ALL
  USING (public.is_admin()) WITH CHECK (public.is_admin());

INSERT INTO public.parroquias (cod_parroquia, nombre, canton, provincia, geom)
