ON CONFLICT (cod_parroquia) DO UPDATE SET nombre = EXCLUDED.nombre, geom = EXCLUDED.geom;

UPDATE public.parroquias p SET poblacion = v.pob FROM (VALUES
  ('110150', 214296), ('110151', 1025), ('110152', 2114), ('110153', 1639), ('110154', 2082),
  ('110155', 1010), ('110156', 8669), ('110157', 4686), ('110158', 1305), ('110159', 1051),
  ('110160', 3720), ('110161', 5516), ('110162', 1413), ('110163', 1502)
) AS v(cod, pob) WHERE p.cod_parroquia = v.cod;

-- Agregados del ECU 911. dia_semana: 0 = domingo ... 6 = sabado (como EXTRACT(DOW)).
CREATE TABLE IF NOT EXISTS public.incidentes_agregados (
  id BIGSERIAL PRIMARY KEY,
  cod_parroquia TEXT NOT NULL REFERENCES public.parroquias(cod_parroquia),
  servicio TEXT NOT NULL,
  subtipo TEXT NOT NULL DEFAULT '',
  anio SMALLINT NOT NULL CHECK (anio BETWEEN 2000 AND 2100),
  mes SMALLINT NOT NULL CHECK (mes BETWEEN 1 AND 12),
  dia_semana SMALLINT NOT NULL CHECK (dia_semana BETWEEN 0 AND 6),
  conteo INTEGER NOT NULL CHECK (conteo >= 0),
  fuente TEXT NOT NULL DEFAULT 'SIS ECU 911 - Base de Emergencias (datosabiertos.gob.ec, CC-BY)',
  fecha_carga TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (cod_parroquia, servicio, subtipo, anio, mes, dia_semana)
);
CREATE INDEX IF NOT EXISTS incidentes_agregados_periodo_idx ON public.incidentes_agregados(anio, mes);
ALTER TABLE public.incidentes_agregados ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Incidentes agregados: lectura publica" ON public.incidentes_agregados;
CREATE POLICY "Incidentes agregados: lectura publica" ON public.incidentes_agregados FOR SELECT USING (true);
DROP POLICY IF EXISTS "Incidentes agregados: gestion admin" ON public.incidentes_agregados;
CREATE POLICY "Incidentes agregados: gestion admin" ON public.incidentes_agregados FOR ALL
  USING (public.is_admin()) WITH CHECK (public.is_admin());

CREATE TABLE IF NOT EXISTS public.importaciones_ecu911 (
  id BIGSERIAL PRIMARY KEY,
  periodo TEXT NOT NULL CHECK (periodo ~ '^[0-9]{4}-[0-9]{2}$'),
  archivo TEXT NOT NULL,
  filas INTEGER NOT NULL DEFAULT 0,
  filas_loja INTEGER NOT NULL DEFAULT 0,
  estado TEXT NOT NULL CHECK (estado IN ('ok', 'error')),
  mensaje TEXT,
  fecha TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE public.importaciones_ecu911 ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Importaciones: lectura admin" ON public.importaciones_ecu911;
CREATE POLICY "Importaciones: lectura admin" ON public.importaciones_ecu911 FOR SELECT USING (public.is_admin());

-- Reemplaza los agregados de los periodos del lote y registra la importacion, todo en una
-- transaccion (la funcion es atomica). p_agregados: [{cod_parroquia, servicio, subtipo, anio,
-- mes, dia_semana, conteo}]. Solo service_role o admin.
CREATE OR REPLACE FUNCTION public.reemplazar_incidentes_ecu911(
  p_agregados JSONB, p_archivo TEXT, p_filas INTEGER, p_filas_loja INTEGER
) RETURNS INTEGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  n INTEGER;
  periodos TEXT;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND NOT public.is_admin() THEN
    RAISE EXCEPTION 'Solo service_role o admin pueden importar' USING ERRCODE = '42501';
  END IF;
  CREATE TEMP TABLE IF NOT EXISTS _lote_ecu911 (
    cod_parroquia TEXT, servicio TEXT, subtipo TEXT, anio SMALLINT, mes SMALLINT,
    dia_semana SMALLINT, conteo INTEGER
  ) ON COMMIT DROP;
  TRUNCATE _lote_ecu911;
  INSERT INTO _lote_ecu911
    SELECT x.cod_parroquia, x.servicio, COALESCE(x.subtipo, ''), x.anio, x.mes, x.dia_semana, x.conteo
    FROM jsonb_to_recordset(p_agregados) AS x(cod_parroquia TEXT, servicio TEXT, subtipo TEXT,
      anio SMALLINT, mes SMALLINT, dia_semana SMALLINT, conteo INTEGER)
    WHERE x.cod_parroquia IN (SELECT cod_parroquia FROM parroquias);
  DELETE FROM incidentes_agregados a USING (SELECT DISTINCT anio, mes FROM _lote_ecu911) p
    WHERE a.anio = p.anio AND a.mes = p.mes;
  INSERT INTO incidentes_agregados (cod_parroquia, servicio, subtipo, anio, mes, dia_semana, conteo)
    SELECT cod_parroquia, servicio, subtipo, anio, mes, dia_semana, sum(conteo)::int
    FROM _lote_ecu911 GROUP BY 1, 2, 3, 4, 5, 6;
  GET DIAGNOSTICS n = ROW_COUNT;
  SELECT string_agg(DISTINCT lpad(anio::text, 4, '0') || '-' || lpad(mes::text, 2, '0'), ',')
    INTO periodos FROM _lote_ecu911;
  INSERT INTO importaciones_ecu911 (periodo, archivo, filas, filas_loja, estado, mensaje)
    VALUES (COALESCE(split_part(periodos, ',', 1), to_char(now(), 'YYYY-MM')), p_archivo, p_filas,
            p_filas_loja, 'ok', 'Periodos: ' || COALESCE(periodos, 'ninguno') || '; agregados: ' || n);
  RETURN n;
END;
$$;
REVOKE ALL ON FUNCTION public.reemplazar_incidentes_ecu911(JSONB, TEXT, INTEGER, INTEGER) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.reemplazar_incidentes_ecu911(JSONB, TEXT, INTEGER, INTEGER) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.registrar_error_ecu911(p_archivo TEXT, p_mensaje TEXT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND NOT public.is_admin() THEN
    RAISE EXCEPTION 'Solo service_role o admin' USING ERRCODE = '42501';
  END IF;
  INSERT INTO importaciones_ecu911 (periodo, archivo, estado, mensaje)
    VALUES (to_char(now() AT TIME ZONE 'America/Guayaquil', 'YYYY-MM'), p_archivo, 'error', left(p_mensaje, 500));
END;
$$;
REVOKE ALL ON FUNCTION public.registrar_error_ecu911(TEXT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.registrar_error_ecu911(TEXT, TEXT) TO authenticated, service_role;

-- Reportes de usuarios ------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.incidentes_usuario (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE CASCADE,
  tipo TEXT NOT NULL CHECK (tipo IN ('robo_asalto', 'acoso', 'perros_agresivos',
    'iluminacion_deficiente', 'trafico_peligroso', 'via_mal_estado', 'accidente', 'otro')),
  descripcion TEXT CHECK (char_length(descripcion) <= 280),
  geom geometry(Point, 4326) NOT NULL,
  direccion TEXT CHECK (char_length(direccion) <= 200),
  ocurrido_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  fotos TEXT[] NOT NULL DEFAULT '{}' CHECK (cardinality(fotos) <= 3),
  estado TEXT NOT NULL DEFAULT 'pendiente' CHECK (estado IN ('pendiente', 'verificado', 'rechazado')),
  confirmaciones INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (ocurrido_at <= created_at + interval '5 minutes' AND ocurrido_at >= created_at - interval '7 days')
);
CREATE INDEX IF NOT EXISTS incidentes_usuario_geom_idx ON public.incidentes_usuario USING gist (geom);
CREATE INDEX IF NOT EXISTS incidentes_usuario_user_idx ON public.incidentes_usuario(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS incidentes_usuario_estado_idx ON public.incidentes_usuario(estado, ocurrido_at DESC);
ALTER TABLE public.incidentes_usuario ENABLE ROW LEVEL SECURITY;

-- Solo el autor (y moderacion) leen la fila completa; el publico usa la vista anonima.
DROP POLICY IF EXISTS "Incidentes: ver los mios" ON public.incidentes_usuario;
CREATE POLICY "Incidentes: ver los mios" ON public.incidentes_usuario FOR SELECT
  USING (user_id = auth.uid() OR public.es_moderador());
DROP POLICY IF EXISTS "Incidentes: reportar" ON public.incidentes_usuario;
CREATE POLICY "Incidentes: reportar" ON public.incidentes_usuario FOR INSERT TO authenticated
  WITH CHECK (user_id = auth.uid() AND estado = 'pendiente' AND confirmaciones = 0
              AND public.consentimiento_vigente(auth.uid(), 'gps_carrera'));
DROP POLICY IF EXISTS "Incidentes: moderar" ON public.incidentes_usuario;
CREATE POLICY "Incidentes: moderar" ON public.incidentes_usuario FOR UPDATE
  USING (public.es_moderador()) WITH CHECK (public.es_moderador());
DROP POLICY IF EXISTS "Incidentes: borrar" ON public.incidentes_usuario;
CREATE POLICY "Incidentes: borrar" ON public.incidentes_usuario FOR DELETE
  USING (user_id = auth.uid() OR public.es_moderador());

-- Antispam: maximo 5 reportes por hora y 20 por dia por usuario.
CREATE OR REPLACE FUNCTION public.trg_incidentes_limite() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF (SELECT count(*) FROM incidentes_usuario WHERE user_id = NEW.user_id
        AND created_at > now() - interval '1 hour') >= 5
     OR (SELECT count(*) FROM incidentes_usuario WHERE user_id = NEW.user_id
        AND created_at > now() - interval '1 day') >= 20 THEN
    RAISE EXCEPTION 'Limite de reportes alcanzado, intenta mas tarde' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS incidentes_limite ON public.incidentes_usuario;
CREATE TRIGGER incidentes_limite BEFORE INSERT ON public.incidentes_usuario
  FOR EACH ROW EXECUTE FUNCTION public.trg_incidentes_limite();

-- "Yo tambien lo vi": una confirmacion por usuario; no se puede confirmar el propio.
CREATE TABLE IF NOT EXISTS public.incidentes_confirmaciones (
  incidente_id UUID NOT NULL REFERENCES public.incidentes_usuario(id) ON DELETE CASCADE,
  user_id UUID NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (incidente_id, user_id)
);
ALTER TABLE public.incidentes_confirmaciones ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Confirmaciones: ver las mias" ON public.incidentes_confirmaciones;
CREATE POLICY "Confirmaciones: ver las mias" ON public.incidentes_confirmaciones FOR SELECT
  USING (user_id = auth.uid() OR public.es_moderador());
DROP POLICY IF EXISTS "Confirmaciones: confirmar" ON public.incidentes_confirmaciones;
CREATE POLICY "Confirmaciones: confirmar" ON public.incidentes_confirmaciones FOR INSERT TO authenticated
  WITH CHECK (user_id = auth.uid());
DROP POLICY IF EXISTS "Confirmaciones: quitar" ON public.incidentes_confirmaciones;
CREATE POLICY "Confirmaciones: quitar" ON public.incidentes_confirmaciones FOR DELETE
  USING (user_id = auth.uid());

CREATE OR REPLACE FUNCTION public.trg_incidentes_confirmar() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF EXISTS (SELECT 1 FROM incidentes_usuario WHERE id = NEW.incidente_id AND user_id = NEW.user_id) THEN
      RAISE EXCEPTION 'No puedes confirmar tu propio reporte' USING ERRCODE = 'P0001';
    END IF;
    UPDATE incidentes_usuario SET confirmaciones = confirmaciones + 1 WHERE id = NEW.incidente_id;
    RETURN NEW;
  END IF;
  UPDATE incidentes_usuario SET confirmaciones = greatest(confirmaciones - 1, 0) WHERE id = OLD.incidente_id;
  RETURN OLD;
END;
$$;
DROP TRIGGER IF EXISTS incidentes_confirmar ON public.incidentes_confirmaciones;
CREATE TRIGGER incidentes_confirmar AFTER INSERT OR DELETE ON public.incidentes_confirmaciones
  FOR EACH ROW EXECUTE FUNCTION public.trg_incidentes_confirmar();

-- Vista anonima: sin user_id ni direccion exacta; posicion redondeada a 3 decimales (~110 m),
-- hora truncada a la hora; descripcion solo si moderacion la verifico. Ultimos 90 dias.
CREATE OR REPLACE VIEW public.incidentes_publicos AS
  SELECT id, tipo,
         CASE WHEN estado = 'verificado' THEN descripcion END AS descripcion,
         round(ST_Y(geom)::numeric, 3)::float8 AS lat,
         round(ST_X(geom)::numeric, 3)::float8 AS lng,
         date_trunc('hour', ocurrido_at) AS ocurrido_hora,
         fotos, estado, confirmaciones
  FROM public.incidentes_usuario
  WHERE estado <> 'rechazado' AND ocurrido_at > now() - interval '90 days';
GRANT SELECT ON public.incidentes_publicos TO anon, authenticated;

-- Storage: bucket publico con nombres aleatorios (sin user_id en la ruta), 3 MB por foto.
-- El cliente quita EXIF/GPS reencodificando la imagen antes de subirla.
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES ('incidentes', 'incidentes', true, 3145728, ARRAY['image/jpeg', 'image/webp'])
ON CONFLICT (id) DO UPDATE SET public = true, file_size_limit = 3145728,
  allowed_mime_types = ARRAY['image/jpeg', 'image/webp'];
DROP POLICY IF EXISTS "Incidentes fotos: subir" ON storage.objects;
CREATE POLICY "Incidentes fotos: subir" ON storage.objects FOR INSERT TO authenticated
  WITH CHECK (bucket_id = 'incidentes' AND name ~ '^[0-9a-f-]{36}/[0-9]\.(jpg|webp)$');
DROP POLICY IF EXISTS "Incidentes fotos: borrar" ON storage.objects;
CREATE POLICY "Incidentes fotos: borrar" ON storage.objects FOR DELETE
  USING (bucket_id = 'incidentes' AND (owner = auth.uid() OR public.es_moderador()));

-- Puntaje de seguridad por ruta ------------------------------------------------------------
-- Indice por parroquia = tasa ECU 911 de ese dia de la semana (incidentes por 1000 hab., ultimos
-- 12 meses cargados) / tasa del canton + peso de reportes de usuarios cercanos (verificados o con
-- 2+ confirmaciones) con decaimiento exponencial de 30 dias, filtrados por franja horaria si
-- p_hora no es NULL. Nivel: < 0.75 bajo, < 1.5 medio, si no alto. tramo = 0 es la ruta completa.
CREATE OR REPLACE FUNCTION public.nivel_seguridad_ruta(
  p_ruta_id TEXT, p_dia_semana INTEGER, p_hora INTEGER DEFAULT NULL
) RETURNS TABLE (tramo INTEGER, cod_parroquia TEXT, parroquia TEXT, indice NUMERIC, nivel TEXT,
                 reportes_usuarios INTEGER)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  WITH ruta AS (
    SELECT r.path FROM routes r
    WHERE r.id = p_ruta_id AND (r.is_public OR r.author_id = auth.uid())
  ),
  puntos AS (
    SELECT i, ST_SetSRID(ST_MakePoint((p->>'lng')::float, (p->>'lat')::float), 4326) AS g
    FROM ruta, jsonb_array_elements(ruta.path) WITH ORDINALITY AS t(p, i)
  ),
  tramos AS (
    SELECT a.i::int AS n, ST_MakeLine(a.g, b.g) AS g FROM puntos a JOIN puntos b ON b.i = a.i + 1
  ),
  ultimo AS (SELECT max(make_date(anio, mes, 1)) AS hasta FROM incidentes_agregados),
  tasas AS (
    SELECT p.cod_parroquia, p.nombre,
           COALESCE(sum(a.conteo), 0)::numeric / greatest(p.poblacion, 1) AS tasa,
           greatest(p.poblacion, 1) AS pob
    FROM parroquias p
    LEFT JOIN incidentes_agregados a ON a.cod_parroquia = p.cod_parroquia
      AND a.dia_semana = p_dia_semana
      AND make_date(a.anio, a.mes, 1) > (SELECT hasta FROM ultimo) - interval '12 months'
    GROUP BY p.cod_parroquia, p.nombre, p.poblacion
  ),
  canton AS (
    SELECT NULLIF(sum(tasa * pob) / sum(pob), 0) AS tasa FROM tasas
  ),
  por_tramo AS (
    SELECT t.n, pa.cod_parroquia, pa.nombre,
      COALESCE(ta.tasa / (SELECT tasa FROM canton), 1) AS base,
      (SELECT COALESCE(sum(exp(-extract(epoch FROM now() - u.ocurrido_at) / (30 * 86400))), 0)
         FROM incidentes_usuario u
         WHERE (u.estado = 'verificado' OR (u.estado = 'pendiente' AND u.confirmaciones >= 2))
           AND u.tipo IN ('robo_asalto', 'acoso', 'perros_agresivos', 'trafico_peligroso', 'accidente',
                          'iluminacion_deficiente', 'via_mal_estado')
           AND u.ocurrido_at > now() - interval '180 days'
           AND ST_DWithin(u.geom::geography, t.g::geography, 150)
           AND (p_hora IS NULL OR abs(extract(hour FROM u.ocurrido_at AT TIME ZONE 'America/Guayaquil') - p_hora) <= 1)
           AND (extract(dow FROM u.ocurrido_at AT TIME ZONE 'America/Guayaquil') = p_dia_semana OR p_hora IS NULL)
      ) AS peso_usuarios,
      (SELECT count(*) FROM incidentes_usuario u
         WHERE (u.estado = 'verificado' OR (u.estado = 'pendiente' AND u.confirmaciones >= 2))
           AND u.ocurrido_at > now() - interval '180 days'
           AND ST_DWithin(u.geom::geography, t.g::geography, 150))::int AS n_usuarios
    FROM tramos t
    LEFT JOIN LATERAL (
      SELECT p.cod_parroquia, p.nombre FROM parroquias p
      WHERE ST_Intersects(p.geom, ST_LineInterpolatePoint(t.g, 0.5)) LIMIT 1
    ) pa ON true
    LEFT JOIN tasas ta ON ta.cod_parroquia = pa.cod_parroquia
  ),
  indices AS (
    SELECT n, cod_parroquia, nombre, round((base + 0.5 * peso_usuarios)::numeric, 2) AS ind, n_usuarios
    FROM por_tramo
  )
  SELECT n, cod_parroquia, nombre, ind,
         CASE WHEN ind < 0.75 THEN 'bajo' WHEN ind < 1.5 THEN 'medio' ELSE 'alto' END, n_usuarios
  FROM indices
  UNION ALL
  SELECT 0, NULL, NULL, round(avg(ind), 2),
         CASE WHEN avg(ind) < 0.75 THEN 'bajo' WHEN avg(ind) < 1.5 THEN 'medio' ELSE 'alto' END,
         COALESCE(sum(n_usuarios), 0)::int
  FROM indices HAVING count(*) > 0
  ORDER BY 1;
$$;
GRANT EXECUTE ON FUNCTION public.nivel_seguridad_ruta(TEXT, INTEGER, INTEGER) TO anon, authenticated;

-- Resumen por parroquia para la tarjeta "Seguridad de la zona": nivel por dia de la semana
-- y servicios mas frecuentes (ultimos 12 meses cargados).
CREATE OR REPLACE FUNCTION public.seguridad_zona_ruta(p_ruta_id TEXT)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  dias JSONB := '[]'::jsonb;
  d INTEGER;
  r RECORD;
  tipos JSONB;
  hasta DATE;
BEGIN
  FOR d IN 0..6 LOOP
    SELECT * INTO r FROM nivel_seguridad_ruta(p_ruta_id, d) WHERE tramo = 0;
    IF FOUND THEN
      dias := dias || jsonb_build_object('dia', d, 'nivel', r.nivel, 'indice', r.indice);
    END IF;
  END LOOP;
  SELECT max(make_date(anio, mes, 1)) INTO hasta FROM incidentes_agregados;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('servicio', servicio, 'subtipo', subtipo, 'conteo', c)
                            ORDER BY c DESC), '[]'::jsonb) INTO tipos
  FROM (
    SELECT a.servicio, a.subtipo, sum(a.conteo)::int AS c FROM incidentes_agregados a
    WHERE a.cod_parroquia IN (SELECT DISTINCT n.cod_parroquia FROM nivel_seguridad_ruta(p_ruta_id, 1) n
                              WHERE n.cod_parroquia IS NOT NULL)
      AND make_date(a.anio, a.mes, 1) > hasta - interval '12 months'
    GROUP BY 1, 2 ORDER BY 3 DESC LIMIT 4
  ) t;
  RETURN jsonb_build_object('dias', dias, 'tipos', tipos,
    'actualizado_hasta', to_char(hasta, 'YYYY-MM'),
    'fuente', 'SIS ECU 911, Base de Emergencias (datosabiertos.gob.ec, CC-BY) y reportes de corredores');
END;
$$;
GRANT EXECUTE ON FUNCTION public.seguridad_zona_ruta(TEXT) TO anon, authenticated;
